	'sc_s2_t' => 'Menus et plan d’effectifs',
	'sc_s2_b' => 'Notre diététicienne et notre chef écrivent le premier cycle de quatre semaines et nous convenons du nombre de membres d’équipe nécessaires à chaque équipe, à raison d’un pour 40 déjeuners.',
	'alt_m02_sc' => 'Deux cuisiniers découpent des légumes frais sur un long plan de travail, dans la lumière du petit matin.',
	'sc_s3_time' => 'Semaine 6',
	'sc_s3_t' => 'Semaine d’essai',
