	'ab_s2_b' => 'L’entreprise s’est étendue à des usines et à un collège technique, et a écrit le cycle de menus de quatre semaines qu’elle utilise encore.',
	'alt_m07_ab' => 'Étudiants et personnel font la queue au comptoir de service d’un restaurant universitaire.',
	'ab_s3_time' => '2024',
